#include <linux/slab.h>
#include <linux/uaccess.h>

int timer_init_and_select(struct file *file, struct snd_timer_select __user *user_select) {
    struct snd_timer *timer = file->private_data;
    struct snd_timer_select kernel_select = {0};
    int ret = 0;

    if (timer) {
        timer_close(timer);
    }

    if (copy_from_user(&kernel_select, user_select, sizeof(kernel_select))) {
        return -EFAULT;
    }

    timer = kzalloc(sizeof(*timer), GFP_KERNEL);
    if (!timer) {
        return -ENOMEM;
    }

    timer->queues = kcalloc(kernel_select.queues, sizeof(*timer->queues), GFP_KERNEL);
    if (!timer->queues) {
        kfree(timer);
        return -ENOMEM;
    }

    file->private_data = timer;
    timer->file = file;

    timer->open = timer_open;
    timer->close = timer_close;
    timer->start = timer_start;
    timer->stop = timer_stop;
    timer->pointer = timer_pointer;

    timer->fast = 1;

    return 0;
}
